namespace JingFamily {
 public static class Ui {
  public static Bitmap Logo(){using(var s=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("JingPuLogo"))using(var img=Image.FromStream(s))return new Bitmap(img);}
  public static void ApplyBrand(Form form){using(var s=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("JingPuIcon"))using(var icon=new Icon(s)){form.Icon=(Icon)icon.Clone();}form.Shown+=(s,e)=>StudioStyle.Polish(form);form.Disposed+=(s,e)=>{if(form.Icon!=null)form.Icon.Dispose();};}
  public static Color Green=StudioStyle.Green, Cream=StudioStyle.Canvas, Gold=StudioStyle.Gold, Ink=StudioStyle.Ink;
  public static Font Font(float size=10,FontStyle style=FontStyle.Regular){return new Font("Microsoft YaHei UI",size,style);}
  public static Button Button(string text,Action action,bool primary=false){var b=new StudioButton{Text=text,Font=Font(9.5f),AutoSize=true,Height=39,MinimumSize=new Size(86,39),FlatStyle=FlatStyle.Flat,BackColor=primary?Green:Color.White,ForeColor=primary?Color.White:Green,Margin=new Padding(0,0,9,8),Padding=new Padding(10,2,10,2),Cursor=Cursors.Hand};b.FlatAppearance.BorderColor=primary?Green:Color.FromArgb(211,219,211);b.Click+=(s,e)=>{try{action();}catch(Exception ex){Error(ex);}};return b;}
  public static void Error(Exception e){while(e is System.Reflection.TargetInvocationException&&e.InnerException!=null)e=e.InnerException;BrandMessage.Show("操作未完成",e.Message,false);}
  public static bool Confirm(string text){return BrandMessage.Show("请确认",text,true)==DialogResult.Yes;}
  public static void Info(string text){BrandMessage.Show("景·谱",text,false);}
  public static string SavePath(string filter,string name){using(var d=new SaveFileDialog{Filter=filter,FileName=name,OverwritePrompt=true})return d.ShowDialog()==DialogResult.OK?d.FileName:null;}
  public static string OpenPath(string filter){using(var d=new OpenFileDialog{Filter=filter})return d.ShowDialog()==DialogResult.OK?d.FileName:null;}
  public static Label Label(string text,float size=10,bool bold=false){return new Label{Text=text,AutoSize=true,Font=Font(size,bold?FontStyle.Bold:FontStyle.Regular),ForeColor=Ink,Margin=new Padding(0,0,0,10)};}
  public static void Open(string path){System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(path){UseShellExecute=true});}
  public static DataGridView Grid(){var g=new StudioGrid{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AllowUserToResizeRows=false,RowHeadersVisible=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,BackgroundColor=Color.White,BorderStyle=BorderStyle.None,CellBorderStyle=DataGridViewCellBorderStyle.SingleHorizontal,GridColor=Color.FromArgb(235,237,230),EnableHeadersVisualStyles=false,ColumnHeadersHeight=48,ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.DisableResizing};g.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(231,236,228);g.ColumnHeadersDefaultCellStyle.ForeColor=Green;g.ColumnHeadersDefaultCellStyle.Font=Font(10,FontStyle.Bold);g.DefaultCellStyle.Font=Font(10);g.DefaultCellStyle.SelectionBackColor=Color.FromArgb(220,234,222);g.DefaultCellStyle.SelectionForeColor=Ink;g.RowTemplate.Height=48;g.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(249,251,248);g.DefaultCellStyle.Padding=new Padding(12,0,8,0);g.ColumnHeadersDefaultCellStyle.Padding=new Padding(12,0,8,0);g.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(238,244,239);g.DefaultCellStyle.SelectionBackColor=Color.FromArgb(224,240,229);g.ColumnHeadersDefaultCellStyle.Font=Font(9.5f,FontStyle.Bold);g.CellPainting+=StatusCell;return g;}
  public static void Columns(DataGridView g,params string[] cols){foreach(string c in cols)g.Columns.Add("c"+g.Columns.Count,c);}
  public static Button Danger(string text,Action action){var b=Button(text,action,true);b.BackColor=StudioStyle.Red;return b;}
  static void StatusCell(object sender,DataGridViewCellPaintingEventArgs e){var g=(DataGridView)sender;if(e.RowIndex<0||e.ColumnIndex<0||e.Value==null)return;string header=g.Columns[e.ColumnIndex].HeaderText;if(header!="状态"&&header!="当前")return;string text=e.Value.ToString();if(text=="")return;e.PaintBackground(e.ClipBounds,true);bool red=text.Contains("失败")||text.Contains("逾期")||text.Contains("未完成删除");bool good=text.Contains("正常")||text.Contains("使用中")||text.Contains("已完成")||text.Contains("可恢复");Color bg=red?Color.FromArgb(251,236,231):good?Color.FromArgb(225,240,228):Color.FromArgb(241,241,231),fg=red?StudioStyle.Red:good?Ui.Green:Color.FromArgb(131,115,71);using(var font=Font(8.7f,FontStyle.Bold)){int width=Math.Min(e.CellBounds.Width-14,TextRenderer.MeasureText(text,font).Width+20);var r=new Rectangle(e.CellBounds.X+7,e.CellBounds.Y+10,Math.Max(10,width),e.CellBounds.Height-20);e.Graphics.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;using(var path=StudioStyle.Round(r,7))using(var b=new SolidBrush(bg))e.Graphics.FillPath(b,path);TextRenderer.DrawText(e.Graphics,text,font,r,fg,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);}e.Handled=true;}
  public static string DateLabel(string date){return String.IsNullOrEmpty(date)?"未记录":date;}
 }
 public class PickItem {public string Id,Name;public PickItem(string id,string name){Id=id;Name=name;}public override string ToString(){return Name;}}
 public class BrandMessage:Form {
  public BrandMessage(string title,string message,bool confirm){Text=title=="景·谱"?title:title+" · 景·谱";Ui.ApplyBrand(this);Font=Ui.Font();Size=new Size(650,Math.Min(700,Math.Max(300,170+message.Split('\n').Length*26)));MinimumSize=new Size(520,280);StartPosition=FormStartPosition.CenterParent;BackColor=Ui.Cream;ShowInTaskbar=false;var top=new Panel{Dock=DockStyle.Top,Height=76,Padding=new Padding(20)};top.Controls.Add(new PictureBox{Image=Ui.Logo(),Location=new Point(22,16),Size=new Size(44,44),SizeMode=PictureBoxSizeMode.Zoom});top.Controls.Add(new Label{Text=title,Font=Ui.Font(15,FontStyle.Bold),ForeColor=Ui.Green,AutoSize=true,Location=new Point(80,22)});Controls.Add(top);var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=62,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(15,10,10,0)};var ok=Ui.Button(confirm?"确认":"确定",()=>DialogResult=confirm?DialogResult.Yes:DialogResult.OK,true);bottom.Controls.Add(ok);AcceptButton=ok;if(confirm){var cancel=Ui.Button("取消",()=>DialogResult=DialogResult.No);bottom.Controls.Add(cancel);CancelButton=cancel;}Controls.Add(bottom);var text=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BorderStyle=BorderStyle.None,BackColor=Ui.Cream,Text=message};var body=new Panel{Dock=DockStyle.Fill,Padding=new Padding(22,0,22,12)};body.Controls.Add(text);Controls.Add(body);body.BringToFront();}
  public static DialogResult Show(string title,string message,bool confirm){using(var dialog=new BrandMessage(title,message,confirm)){var owner=Form.ActiveForm;return owner==null?dialog.ShowDialog():dialog.ShowDialog(owner);}}
 }
 public class Editor:Form {
  protected TableLayoutPanel Fields;
  protected Panel Body;
  public Editor(string title,int width=660,int height=650){Text=title;Ui.ApplyBrand(this);Size=new Size(width,height);MinimumSize=new Size(550,450);StartPosition=FormStartPosition.CenterParent;Font=Ui.Font();BackColor=Ui.Cream;ForeColor=Ui.Ink;ShowInTaskbar=false;var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=72,BackColor=Color.White,Padding=new Padding(20,16,16,0),FlowDirection=FlowDirection.RightToLeft};var ok=Ui.Button("保存",()=>{if(Commit())DialogResult=DialogResult.OK;},true);footer.Controls.Add(ok);footer.Controls.Add(Ui.Button("取消",()=>DialogResult=DialogResult.Cancel));AcceptButton=ok;Controls.Add(footer);var banner=new Panel{Dock=DockStyle.Top,Height=84,BackColor=Color.White};banner.Controls.Add(new PictureBox{Image=Ui.Logo(),Location=new Point(25,20),Size=new Size(44,44),SizeMode=PictureBoxSizeMode.Zoom});banner.Controls.Add(new Label{Text=title,Font=Ui.Font(12,FontStyle.Bold),ForeColor=Ui.Green,AutoSize=true,Location=new Point(84,26),MaximumSize=new Size(width-120,32)});Controls.Add(banner);Body=new Panel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(22)};Controls.Add(Body);Body.BringToFront();Fields=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=2,Padding=new Padding(0,0,15,0)};Fields.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,100));Fields.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));Body.Controls.Add(Fields);}
  protected virtual bool Commit(){return true;}
  protected void Field(string label,Control c,int height=46){int row=Fields.RowCount++;Fields.RowStyles.Add(new RowStyle(SizeType.Absolute,height));var l=Ui.Label(label);l.Margin=new Padding(0,13,0,0);l.Font=Ui.Font(9.5f);l.ForeColor=StudioStyle.Muted;Fields.Controls.Add(l,0,row);Control field=(c is TextBox||c is ComboBox)?new InputFrame(c):c;field.Dock=DockStyle.Fill;field.Margin=new Padding(0,2,0,7);Fields.Controls.Add(field,1,row);}
  protected TextBox TextField(string label,string value,bool multi=false){var t=new TextBox{Text=value,Multiline=multi,ScrollBars=multi?ScrollBars.Vertical:ScrollBars.None};Field(label,t,multi?128:48);return t;}
  protected ComboBox PersonField(string label,string id,string exclude=""){var c=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};c.Items.Add(new PickItem("","— 未指定 —"));foreach(var p in Store.Data.People.Where(x=>x.Id!=exclude).OrderBy(x=>x.Name))c.Items.Add(new PickItem(p.Id,p.Name+"  "+p.Birth+"  ["+p.Id.Substring(0,Math.Min(6,p.Id.Length))+"]"));c.SelectedIndex=0;for(int i=0;i<c.Items.Count;i++)if(((PickItem)c.Items[i]).Id==id)c.SelectedIndex=i;Field(label,c);return c;}
  protected string Id(ComboBox c){return ((PickItem)c.SelectedItem).Id;}
 }
 public class PersonEditor:Editor {
  Person original;TextBox name,birth,death,place,address,phone,job,generation,bio;ComboBox gender,father,mother;CheckedListBox spouses;string portrait;Label photoLabel;
  public PersonEditor(Person p):base(p==null?"添加成员":"编辑成员 · "+p.Name,720,850){original=p;var q=p??new Person();portrait=q.Portrait;name=TextField("姓名 *",q.Name);gender=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};gender.Items.AddRange(new[]{"男","女","未知"});gender.SelectedItem=q.Gender;if(gender.SelectedIndex<0)gender.SelectedIndex=2;Field("性别",gender);birth=TextField("出生日期",q.Birth);death=TextField("去世日期",q.Death);Field("日期格式",Ui.Label("YYYY / YYYY-MM / YYYY-MM-DD；未知可留空",9),34);place=TextField("籍贯",q.Place);generation=TextField("字辈",q.Generation);father=PersonField("父亲",q.FatherId,q.Id);mother=PersonField("母亲",q.MotherId,q.Id);spouses=new CheckedListBox{CheckOnClick=true,BorderStyle=BorderStyle.FixedSingle};foreach(var x in Store.Data.People.Where(x=>x.Id!=q.Id).OrderBy(x=>x.Name)){int n=spouses.Items.Add(new PickItem(x.Id,x.Name+"  "+x.Birth+"  ["+x.Id.Substring(0,Math.Min(6,x.Id.Length))+"]"));spouses.SetItemChecked(n,q.Spouses.Contains(x.Id));}Field("配偶（可多选）",spouses,95);address=TextField("住址",q.Address);phone=TextField("联系方式",q.Phone);job=TextField("职业",q.Occupation);bio=TextField("生平 / 备注",q.Biography,true);var photos=new FlowLayoutPanel{WrapContents=false};photos.Controls.Add(Ui.Button("选择头像",()=>{string f=Ui.OpenPath("图片|*.jpg;*.jpeg;*.png;*.bmp");if(f!=null){using(var img=Image.FromFile(f)){}portrait=Store.AddMedia(f);photoLabel.Text=Path.GetFileName(f);}}));photos.Controls.Add(Ui.Button("移除",()=>{portrait="";photoLabel.Text="未设置";}));photoLabel=Ui.Label(portrait==""?"未设置":"已设置头像",9);photos.Controls.Add(photoLabel);Field("头像",photos,50);}
  protected override bool Commit(){if(String.IsNullOrWhiteSpace(name.Text))throw new Exception("请填写姓名。");var candidate=new Person{Id=original==null?Guid.NewGuid().ToString("N"):original.Id,Name=name.Text.Trim(),Gender=gender.Text,Birth=birth.Text.Trim(),Death=death.Text.Trim(),Place=place.Text.Trim(),Address=address.Text.Trim(),Phone=phone.Text.Trim(),Occupation=job.Text.Trim(),Generation=generation.Text.Trim(),Biography=bio.Text,FatherId=Id(father),MotherId=Id(mother),Portrait=portrait,Spouses=spouses.CheckedItems.Cast<PickItem>().Select(x=>x.Id).ToList()};var clone=Store.Deserialize(Store.Serialize(Store.Data));clone.People.RemoveAll(x=>x.Id==candidate.Id);clone.People.Add(candidate);foreach(var p in clone.People.Where(x=>x.Id!=candidate.Id)){p.Spouses.Remove(candidate.Id);if(candidate.Spouses.Contains(p.Id))p.Spouses.Add(candidate.Id);}Store.Validate(clone);var old=Store.Data;Store.Data=clone;try{Store.Save();}catch{Store.Data=old;throw;}return true;}
 }
 public class EventEditor:Editor {
  FamilyEvent original;TextBox title,date,place,notes;ComboBox person;
  public EventEditor(FamilyEvent e):base(e==null?"添加家族事件":"编辑家族事件",650,540){original=e;var q=e??new FamilyEvent();title=TextField("标题 *",q.Title);date=TextField("日期",q.Date);Field("日期格式",Ui.Label("YYYY / YYYY-MM / YYYY-MM-DD",9),32);place=TextField("地点",q.Place);person=PersonField("关联成员",q.PersonId);notes=TextField("事件记录",q.Notes,true);}
  protected override bool Commit(){if(String.IsNullOrWhiteSpace(title.Text))throw new Exception("请填写事件标题。");Store.CheckDate(date.Text.Trim());if(original==null){original=new FamilyEvent();Store.Data.Events.Add(original);}original.Title=title.Text.Trim();original.Date=date.Text.Trim();original.Place=place.Text.Trim();original.PersonId=Id(person);original.Notes=notes.Text;Store.Save();return true;}
 }
 public class DocumentEditor:Editor {
  Document original;TextBox title,notes;ComboBox person;string file;Label filename;
  public DocumentEditor(Document d):base(d==null?"添加家族资料":"编辑家族资料",650,490){original=d;var q=d??new Document();file=q.File;title=TextField("资料标题 *",q.Title);person=PersonField("关联成员",q.PersonId);var flow=new FlowLayoutPanel();flow.Controls.Add(Ui.Button("选择文件",()=>{string path=Ui.OpenPath("所有文件|*.*");if(path!=null){if(new FileInfo(path).Length>100L*1024*1024)throw new Exception("单个附件上限为 100 MB。");file=Store.AddMedia(path);filename.Text=Path.GetFileName(path);if(title.Text=="")title.Text=Path.GetFileNameWithoutExtension(path);}}));filename=Ui.Label(file==""?"未选择文件":"已保存附件",9);flow.Controls.Add(filename);Field("附件 *",flow,52);notes=TextField("来源 / 说明",q.Notes,true);}
  protected override bool Commit(){if(String.IsNullOrWhiteSpace(title.Text)||file=="")throw new Exception("请填写标题并选择附件。");if(original==null){original=new Document();Store.Data.Documents.Add(original);}original.Title=title.Text.Trim();original.PersonId=Id(person);original.File=file;original.Notes=notes.Text;Store.Save();return true;}
 }
 public class FamilyEditor:Editor {
  TextBox title,motto,history;
  public FamilyEditor():base("家谱设置",650,540){title=TextField("家谱名称 *",Store.Data.Title);motto=TextField("家训 / 寄语",Store.Data.Motto);history=TextField("家族简介",Store.Data.History,true);}
  protected override bool Commit(){if(String.IsNullOrWhiteSpace(title.Text))throw new Exception("请填写家谱名称。");Store.Data.Title=title.Text.Trim();Store.Data.Motto=motto.Text;Store.Data.History=history.Text;Store.Save();return true;}
 }
}
